import os
from typing import Any, Dict, Optional

import requests


def _first_present(*values: Optional[str]) -> Optional[str]:
    for value in values:
        if value:
            return value
    return None


def _normalize_claims(claims: Dict[str, Any]) -> Dict[str, Any]:
    normalized = dict(claims)

    # Standardize common claim names.
    if "sub" in normalized and "user_id" not in normalized:
        normalized["user_id"] = normalized["sub"]

    if "email_verified" in normalized:
        normalized["email_verified"] = bool(normalized["email_verified"])

    if "nickname" not in normalized:
        normalized["nickname"] = _first_present(
            normalized.get("preferred_username"),
            normalized.get("given_name"),
            normalized.get("name"),
        )

    if "display_name" not in normalized:
        normalized["display_name"] = _first_present(
            normalized.get("name"),
            f"{normalized.get('given_name', '')} {normalized.get('family_name', '')}".strip() or None,
            normalized.get("nickname"),
            normalized.get("email"),
        )

    if "provider" not in normalized:
        normalized["provider"] = "auth0"

    return normalized


def fetch_and_normalize_federated_user_profile(
    access_token: str,
    domain: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Fetch federated user profile claims from Auth0's OIDC userinfo endpoint and normalize them.

    Environment variables:
      - AUTH0_DOMAIN: Auth0 tenant domain, e.g. "your-tenant.us.auth0.com"
      - AUTH0_ACCESS_TOKEN: optional fallback access token
    """
    auth0_domain = domain or os.getenv("AUTH0_DOMAIN")
    if not auth0_domain:
        raise ValueError("Missing Auth0 domain. Set AUTH0_DOMAIN or pass domain.")

    token = access_token or os.getenv("AUTH0_ACCESS_TOKEN")
    if not token:
        raise ValueError("Missing access token. Pass access_token or set AUTH0_ACCESS_TOKEN.")

    userinfo_url = f"https://{auth0_domain}/userinfo"
    response = requests.get(
        userinfo_url,
        headers={"Authorization": f"Bearer {token}"},
        timeout=15,
    )
    response.raise_for_status()

    claims = response.json()
    if not isinstance(claims, dict):
        raise ValueError("Unexpected userinfo response format; expected a JSON object.")

    return _normalize_claims(claims)
